class Solution { fun minimumTimeToInitialState(word:String,k:Int):Int{val n=word.length;val z=IntArray(n);var left=0;var right=0;for(index in 1 until n){if(index<=right)z[index]=minOf(right-index+1,z[index-left]);while(index+z[index]<n&&word[z[index]]==word[index+z[index]])z[index]++;if(index+z[index]-1>right){left=index;right=index+z[index]-1}};var shift=k;while(shift<n){if(z[shift]>=n-shift)return shift/k;shift+=k};return (n+k-1)/k} }
